    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // Each thread computes 4 output elements (2x2 block)
    float sum00 = 0.0f;
    float sum01 = 0.0f;
    float sum10 = 0.0f;
    float sum11 = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory (double buffered)
        int a_col = t * TILE_SIZE + tx;
        int a_row = by * TILE_SIZE + ty;

        if (a_row < N && a_col < N) {
            As[0][ty][tx] = A[a_row * N + a_col];
        } else {
            As[0][ty][tx] = 0.0f;
        }

